const serverAddress = app.var.serverAddress.get();
let protocol = '';
let domain = '';

const log = utils.createLogger('download-tail');
const logMapping = utils.createLogger('mapping-to-export-table-error');
if (serverAddress) {
    const [_protocol, _domain] = serverAddress.split('://')
    protocol = _protocol ? _protocol : 'http';
    domain = _domain ? _domain : 'localhost:5008'
}

async function downloadTail({ tail }) {
    const result = await page.fetch.downloadTail({ downloadEntries: [{ "Module": "ESNAAD_M" }, { "Module": "MIS_FM_SI", "Params": [tail] }] }, {
        mapRequest: params => {
            return {
                request: params.request,
                body: app.var.requestEncrypted.get() ? utils.encryptObject(params.body) : params.body
            }
        }
    });
    log.debug('downloading tail', tail);
    const error = result.error;
    const { Result, ErrorMessage, ErrorCode } = utils.toDefault(result.data, { Result: { DownloadId: '' }, ErrorMessage: '', ErrorCode: '' });
    if (ErrorCode === 'ADM.002.001') {
        const action = await alertBox({
            message: `Session is expired, or invalid permission`,
            buttons: [{
                id: 'login',
                label: 'I would like to go back to login page',
                icon: 'IoIosLogIn'
            }, {
                id: 'retry',
                label: 'Please retry again',
                icon: 'IoMdRefresh'
            }]
        })
        if (action === 'login') {
            return navigate('esnaadm/app/login');
        }
        if (action === 'retry') {
            return await downloadTail({ tail })
        }
    }
    if (error || ErrorMessage) {
        await alertBox({
            message: `Error ${error}`
        })
        return;
    }
    const downloadId = Result.DownloadId;
    log.debug('locking tail', tail);
    const locked = await page.call.lockTail(tail);
    if (locked) {
        log.debug('tail', tail, 'LOCKED');
        try {
            await runDownload(downloadId);
        } catch (err) {
            log.error('error while downloading tail', tail,err);
            await page.call.unlockTail(tail)
            log.debug('tail', tail, 'UNLCOKED');
        }

    } else {
        log.debug('unable to lock', tail);
    }
}

module.exports = downloadTail

const MAX_ATTEMPT = 100;
async function runDownload(attachmentId) {
    let attemp = 0
    let isReady = false;
    while (!isReady && attemp < MAX_ATTEMPT) {
        log.debug('checking if sqlite is ready for', attemp, 'time');
        const result = await checkIfDownloadIsReady(attachmentId);
        const readyUnknown = result && typeof result === 'object' && 'success' in result && result.success;
        const lineItems = result && typeof result === 'object' && 'lineItems' in result && result.lineItems;
        isReady = utils.toBoolean(readyUnknown)
        if (lineItems && Array.isArray(lineItems)) {
            page.var.downloadLineItems.set(lineItems);
            page.var.refreshGrid.set(Date.now())
        }
        attemp++;
    }
    if (isReady) {
        log.debug('sqlite is ready to be downloaded');
        await downloadTheFile(attachmentId);
        navigate('esnaadm/app/home');
    } else {
        log.debug('Trying to download for', attemp, 'times', 'but it seems the file takes too long to generate, exiting the process');
    }
}

function checkIfDownloadIsReady(attachmentId) {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            utils.fetch(`${protocol}://${domain}/EsnaadMAppFacade/CheckDownloadProgress?downloadId=${attachmentId}`, { credentials: 'include' }).then(json => {
                const data = utils.toDefault(json.data, { Success: true, Result: { Status: '', ErrorMessage: '', ModuleStatuses: [{ Module: '', Status: '', TableStatuses: [] }] } })
                if (data.Success) {
                    const error = data.Result.ErrorMessage;
                    if (error) {
                        alertBox({ message: error, icon: 'IoMdBriefcase', title: 'Unable to download' });
                        reject(new Error(error))
                        return;
                    }
                    const lineItems = data.Result.ModuleStatuses.map(module => {
                        return module.TableStatuses.map(ts => {
                            return {
                                module: module.Module,
                                moduleStatus: module.Status,
                                table: ts.Table,
                                tableStatus: ts.Status
                            }
                        })
                    }).flat();
                    resolve({ success: data.Result.Status === 'Completed', lineItems })
                    return;
                }
                reject({ message: 'Unable to check download progress' });
            }).catch(err => {
                reject(err)
            })
        }, 1000);
    })
}

async function downloadTheFile(attachmentId) {
    const tailNumber = utils.toString(utils.getItem('tail-number'));
    log.debug('downloading sqlite with id', attachmentId);
    const response = await utils.fetch(`${protocol}://${domain}/home/DownloadEsnaadMData?downloadId=${attachmentId}`, { credentials: 'include' });
    if (response.error) {
        log.debug('downloading sqlite with id', attachmentId, 'Error', response.error);
        alertBox({ message: 'Error' + response.error })
        return;
    }
    const arrayBuffer = utils.toDefault(response.data, new ArrayBuffer(0));
    await tools.saveSqlLite('esnaadm', utils.toDefault(arrayBuffer, new ArrayBuffer(0)));
    log.debug('Succesfully save sqlite!');
    try {
        await populateOutgoingTableFaults(tailNumber);
        await populateOutgoingTableMissions(tailNumber);
        await populateOutgoingTableInspections(tailNumber);
    } catch (err) {
        await alertBox({
            message: 'Datamapping error please contact Esnaad team to check at the backend.<br>' + err.message
        });
        await tools.deleteSqlLite('esnaadm');
        window.location.reload()
        return;
    }
    utils.setItem('synced-date', utils.dateToString(new Date()))
    utils.setItem('database-size', (arrayBuffer.byteLength / (1024 * 1024)).toFixed(1))
    utils.setItem('database-id', attachmentId);
    await db.commit('esnaadm');
    await alertBox({
        message: `The aircraft with tail number ${tailNumber} has been downloaded into the local database and is ready to use in offline mode.`,
    })
    app.var.tailNumber.set(tailNumber);
    log.debug('Download tail', tailNumber, 'COMPLETE');
}

async function populateOutgoingTableMissions(tailNo) {
    const { data } = await app.query.getTailBattalionAndCommandFromTailNumber({ params: { tailNumber: tailNo } });
    if (data.length === 0) {
        return;
    }
    const unitId = data[0].TAIL_UNIT_ID_
    const missions = await db.read('esnaadm', 'OPS_TRN_MISSIONS', {});
    for (const mission of missions) {
        log.debug('Mapping MISSIONS', mission?.ID_);
        await db.record('esnaadm', 'MISSIONS', {
            ABORT_REASON: mission.ABORT_REASON,
            ABORT_REASON_ID: mission.ABORT_REASON_ID,
            ACCESS_CODES_: mission.ACCESS_CODES_,
            CALL_ID: mission.CALL_ID,
            CANCEL_REASON: mission.CANCEL_REASON,
            CANCEL_REASON_ID: mission.CANCEL_REASON_ID,
            CANCEL_REASON_RMKS_: mission.CANCEL_REASON_RMKS_,
            CREATED_BY_: mission.CREATED_BY_,
            CREATED_ON_: mission.CREATED_ON_,
            DATE_: mission.DATE_,
            DESCRIPTION_: mission.DESCRIPTION_,
            EXTERNAL_ID: mission.EXTERNAL_ID,
            MISSION_ID_: mission.ID_,
            MISSION_NO_: mission.MISSION_NO_,
            MISS_PLAN_TYPE_: mission.MISS_PLAN_TYPE_,
            MISS_SUB_TYPE_ID: mission.MISS_SUB_TYPE_ID,
            MOD_BY_: mission.MOD_BY_,
            MOD_ON_: mission.MOD_ON_,
            PLTF_CFG_FUEL_UOM_ID: mission.PLTF_CFG_FUEL_UOM_ID,
            PLTF_CFG_ID: mission.PLTF_CFG_ID,
            PLTF_CFG_MNT_REM_: mission.PLTF_CFG_MNT_REM_,
            PLTF_CFG_NO_OF_PASS_: mission.PLTF_CFG_NO_OF_PASS_,
            PLTF_CFG_REQ_FUEL_: mission.PLTF_CFG_REQ_FUEL_,
            ROUTE_: mission.ROUTE_,
            SUBMT_BY_: mission.SUBMT_BY_,
            SUBMT_ON_: mission.SUBMT_ON_,
            SUPPORT_SUB_UNIT_ID: mission.SUPPORT_SUB_UNIT_ID,
            TERM_: mission.TERM_,
            UNIT_ID_: unitId
        });
        log.debug('Mapping MISSIONS', mission?.ID_, 'SUCCESS');
    }

    const wings = await db.read('esnaadm', 'OPS_TRN_WINGS', {});
    for (const wing of wings) {
        log.debug('Mapping WINGS', wing?.ID_);
        await db.record('esnaadm', 'WINGS', {
            COY_ID: wing.COY_ID,
            IDX_: wing.IDX_,
            MISSION_ID_: wing.MISSION_ID,
            MISSION_WING_ID_: wing.ID_,
            PLTF_ID: wing.PLTF_ID,
            UNIT_ID_: unitId
        })
        log.debug('Mapping WINGS', wing?.ID_, 'SUCCESS');
    }

    const flights = await db.read('esnaadm', 'OPS_TRN_FLIGHTS', {});
    for (const flight of flights) {
        log.debug('Mapping FLIGHTS', flight?.ID_);
        await db.record('esnaadm', 'FLIGHTS', {
            BASE_FROM_ID: flight.BASE_FROM_ID,
            BASE_TO_ID: flight.BASE_TO_ID,
            CREATED_BY_: flight.CREATED_BY_,
            CREATED_ON_: flight.CREATED_ON_,
            ETA_: flight.ETA_,
            ETD_: flight.ETD_,
            IDX_: flight.IDX_,
            MISSION_FLIGHT_ID_: flight.ID_,
            MISSION_ID_: flight.MISSION_ID,
            MOD_BY_: flight.MOD_BY_,
            MOD_ON_: flight.MOD_ON_,
            TERM_: flight.TERM_,
            UNIT_ID_: unitId
        });
        log.debug('Mapping FLIGHTS', flight?.ID_, 'SUCCESS');
    }

    const tailCrews = await db.read('esnaadm', 'OPS_TRN_TAIL_CREWS', {});
