const log = utils.createLogger('esnaad-login');
async function login({ userId, password }) {
    log.debug('Logging into esnaad using',userId);
    const response = await page.fetch.loginAuthenticate({ password, userId }, {
        mapRequest: params => {
            return {
                request: params.request,
                body: app.var.requestEncrypted.get() ? utils.encryptObject(params.body) : params.body
            }
        }
    });
    if (response.error) {
        log.error('Unable to login error message',response.error);
        await alertBox({
            message: `Unable to reach server ${response.error}`
        });
        return;
    }

    if (response.data.ErrorCode) {
        if (response.data.ErrorCode === 'ADM.001.004') {
            log.error('Esnaad response with',response.data.ErrorCode,'invalid userId or password');
            await alertBox({
                message: 'Invalid login userId or Password.'
            });
            return;
        }
        if (response.data.ErrorCode === 'ADM.001.008') {
            log.debug('Esnaad response with',response.data.ErrorCode,'session is already active');
            const result = await alertBox({
                message: 'Session is already active, should we force login ?',
                buttons: [{
                    id: 'yes',
                    label: 'Yes force login and logout session in other device',
                    icon: 'IoMdLogIn'
                }, {
                    id: 'no',
                    label: 'No, cancel my action',
                    icon: 'IoIosLogOut'
                }]
            });
            if (result === 'yes') {
                log.debug('User is requesting to force logout other sessions in esnaad');
                await page.fetch.forceLogout({ userId }, {
                    mapRequest: params => {
                        return {
                            request: params.request,
                            body: app.var.requestEncrypted.get() ? utils.encryptObject(params.body) : params.body
                        }
                    }
                });
                return await login({ userId, password });
            }else{
                log.debug('End of login attempt');
            }
        }
        return;
    }
    const { FirstName, MiddleName, LastName } = response.data.Result;
    log.debug('Succesfully logging into esnaad using',userId,[FirstName,MiddleName,LastName].filter(i => i).join(' '));
    return { FirstName, MiddleName, LastName };
}


module.exports = async (params) => {
    const result = await login({ password: params.password, userId: params.userId });
    if (result) {
        // here we are navigateing 
        const { FirstName, MiddleName, LastName } = result;
        const name = [FirstName, MiddleName, LastName].filter(i => i).join(' ');
        utils.setItem('synced-by', `${params.userId} - ${name}`)
        navigate('esnaadm/app/download')
    }
};

