const serverAddress = app.var.serverAddress.get();
let protocol = '';
let domain = '';
if (serverAddress) {
    const [_protocol, _domain] = serverAddress.split('://')
    protocol = _protocol ? _protocol : 'http';
    domain = _domain ? _domain : 'localhost:5008'
}
const log = utils.createLogger('sync-to-esnaad');
module.exports = async () => {

    const result = await alertBox({ message: 'Are you sure you want to sync the data to server ?', buttons: [{ icon: 'IoMdSave', id: 'yes', label: 'Yes' }, { icon: 'IoMdExit', id: 'no', label: 'No' }], title: 'Sync data to Esnaad', icon: 'IoMdCloudUpload' })
    if (result === 'yes') {
        const buffer = await tools.readSqlLite('esnaadm');
        const fileName = utils.getItem('database-id');
        let index = parseInt(utils.toString(utils.getItem('database-index')) ?? '0');
        const blob = new Blob([buffer]);
        const formData = new FormData();
        const fileNameId = `esnaadM-${fileName}-v${index++}.db`;
        formData.append('fileBase', blob, fileNameId);

        const serverAddress = `${protocol}://${domain}/home/UploadEsnaadMData`;
        log.debug('sync to server', serverAddress)
        try {
            const r = await utils.fetch(serverAddress, {
                method: 'POST',
                cache: "no-cache",
                credentials: 'include',
                body: formData
            });

            const response = r.data;
            let syncingHistory = [];

            const history = utils.getItem('syncing-history');
            if (history && Array.isArray(history)) {
                syncingHistory = history;
            }

            syncingHistory.unshift({
                date: utils.dateToString(new Date()),
                file: fileNameId,
                status: r.error ? r.error : 'success', message: response?.statusText, syncedBy: 'TOPIK'
            })
            utils.setItem('syncing-history', syncingHistory);
            utils.setItem('database-index', index.toString());
            const settingsInfo = { ...page.var.settingsInfo.get(), syncingHistory }
            page.var.settingsInfo.set(settingsInfo);
            const statusMessage = r.error ? 'The data failed to be synchronized with the server.' : 'The data has been successfully synchronized with the server.';
            log.debug('sync to server', serverAddress, 'response', statusMessage)
            await alertBox({ message: statusMessage })
            return utils.isEmpty(r.error)
        } catch (err) {
            log.debug('sync to server', serverAddress, 'ERROR', err)
        }

    }

}

