async function checkIfRequiredTiValidation(){
    const result = await db.read('esnaadm','ADM_MST_SIMPLE_REF',{GRP_:'MNT.STS'},{ORDER_ : 'asc'});
    const highRiskStatus = result.filter((_,index) => index > 1).map(i => i.ID_);
