async function populateFault(faultNo) {
    const result = await page.query.faultUnitList({ filter: { FAULT_NO_: { type: 'equal', value: faultNo } } })
    if (!hasValue(result)) {
        return;
    }
    const faultInfo = result.data[0];
    const result2 = await page.query.faultCorrectList({ filter: { FAULT_UNIT_ID_: { type: 'equal', value: faultInfo.FAULT_UNIT_ID_ } } });
    if (!hasValue(result2)) {
        return;
    }
    const faultCorrect = result2.data[0];
    const result3 = await page.query.faultCorrectingItems({ filter: { FAULT_CORRECT_ID_: { type: 'equal', value: faultCorrect.FAULT_CORRECT_ID_ } } })
    const faultCorrectingItems = hasValue(result3) ? result3.data : [];
    const faultState = faultInfo.FAULT_STATE_;
    page.var.faultUnit.set(faultInfo);

    if(faultState === 'Correcting'){
        const {tailStatus} = app.var.appContext.get();
        const totalHour = parseFloat(((tailStatus.hours + tailStatus.recordedHours) / 60).toFixed(1));
        const totalLandings = tailStatus.landings + tailStatus.recordedLandings;
        const totalCycles = tailStatus.cycles + tailStatus.recordedCycles;
        
        faultCorrect.DATE_ = faultCorrect.DATE_ ?? utils.dateToString(new Date());
        faultCorrect.AIRCRAFT_HR_ = faultCorrect.AIRCRAFT_HR_ ?? totalHour;
        faultCorrect.AIRCRAFT_LANDINGS_ = faultCorrect.AIRCRAFT_LANDINGS_ ?? totalLandings;
        faultCorrect.AIRCRAFT_CYCLES_ = faultCorrect.AIRCRAFT_CYCLES_ ?? totalCycles;
        faultCorrect.AIRCRAFT_ROUNDS_ = faultCorrect.AIRCRAFT_ROUNDS_ ?? 0;
    }

    page.var.faultCorrect.set(faultCorrect);
    page.var.faultCorrectingItems.set(faultCorrectingItems);
    page.var.hasNlt.set(!utils.isEmpty(faultInfo.FAULT_INFO_NLT_DATE_))
    page.var.formState.set(faultState);

}

