module.exports = async function findFaultState({faultInfo, faultCorrect, faultCorrectingItems}) {
    const highRiskStatussesId = await getHighRiskStatussesId();
    const hasFaultInfo = isNotEmpty(faultInfo.FAULT_INFO_DATE_);
    const hasFaultCorrection = isNotEmpty(faultCorrect.DATE_) && isNotEmpty(faultCorrect.ACT_DESC_);
    const is132 = faultCorrect.ITEM_TYPE_ === 'Correcting132';
    const hasCorrectingItems = faultCorrectingItems.length > 0;
    const hasUnCorrectingInfo = isNotEmpty(faultInfo.FAULT_UNCORRECTED_DT_BEGIN_) && utils.isEmpty(faultInfo.FAULT_UNCORRECTED_DT_END)
    const allCorrectingItemsAreClosed = faultCorrectingItems.reduce((res, item) => {
        if (!is132) {
            return res && isNotEmpty(item.USR_ID) && isNotEmpty(item.CAT_ID) && isNotEmpty(item.MNT_MAIN_HRS)
        }
        if (is132) {
            const requireTiValidation = highRiskStatussesId.indexOf(item.STS_ID) >= 0;
            return res && isNotEmpty(item.REL_ACT_) && isNotEmpty(item.MNT_MAIN_HRS)
                && isNotEmpty(item.STS_ID) && isNotEmpty(item.USR_ID) && isNotEmpty(item.CAT_ID)
                && isNotEmpty(item.FAULT_CORRECT_ID_) && (requireTiValidation ? isNotEmpty(item.TI_USR_ID) : true)
        }
    }, true);
    const requireTiValidation = highRiskStatussesId.indexOf(faultInfo.FAULT_INFO_STS_ID) >= 0;
    const hasTiValidation = isNotEmpty(faultInfo.FAULT_TI_VAL_DATE_) && isNotEmpty(faultInfo.FAULT_TI_VAL_USR_ID) && isNotEmpty(faultInfo.FAULT_TI_VAL_VAL_)
    const faultIsFinished = hasFaultInfo && hasFaultCorrection && hasCorrectingItems && allCorrectingItemsAreClosed && (requireTiValidation ? hasTiValidation : true);

    if (faultIsFinished) {
        return 'Finished'
    }
    if (hasUnCorrectingInfo) {
        return 'Uncorrecting'
    }
    if (hasCorrectingItems && allCorrectingItemsAreClosed && requireTiValidation && !hasTiValidation) {
        return 'Validating'
    }
    if (hasFaultInfo) {
        return 'Correcting'
    }
}

function isNotEmpty(val) {
    return !utils.isEmpty(val)
}

async function getHighRiskStatussesId() {
    const result = await db.read('esnaadm','ADM_MST_SIMPLE_REF', { GRP_: 'MNT.STS' }, { ORDER_: 'asc' });
    return result.filter((_, index) => index > 1).map(i => i.ID_);
}

