onChange.formula:
module.exports = async (value) => {
    if(value.ACC_STS_ID === undefined || value.ACC_STS_ID === null){
        value.ACC_STS_ID = value.FAULT_INFO_STS_ID;
    }
    const faultCorrect = page.var.faultCorrect.get();
    const isNotValid = utils.isEmpty(faultCorrect.FAULT_UNIT_ID_) || utils.isEmpty(faultCorrect.UNIT_ID_) || utils.isEmpty(faultCorrect.FAULT_CORRECT_ID_) 
    if(isNotValid){
        await alertBox({message : 'Invalid fault, missing faultUnitId, unitId, and faultCorrectId, please close fault and refresh screen'})
        return;
    }
    const faultCorrectingItems = page.var.faultCorrectingItems.get();
    const faultState = await page.call.findFaultState({faultCorrect,faultCorrectingItems,faultInfo:value})
    value.FAULT_STATE_ = faultState;
    if(faultState === 'Correcting'){
        const {tailStatus} = app.var.appContext.get();
        const totalHour = parseFloat(((tailStatus.hours + tailStatus.recordedHours) / 60).toFixed(1));
        const totalLandings = tailStatus.landings + tailStatus.recordedLandings;
        const totalCycles = tailStatus.cycles + tailStatus.recordedCycles;
        
        faultCorrect.DATE_ = faultCorrect.DATE_ ?? utils.dateToString(new Date());
        faultCorrect.AIRCRAFT_HR_ = faultCorrect.AIRCRAFT_HR_ ?? totalHour;
        faultCorrect.AIRCRAFT_LANDINGS_ = faultCorrect.AIRCRAFT_LANDINGS_ ?? totalLandings;
        faultCorrect.AIRCRAFT_CYCLES_ = faultCorrect.AIRCRAFT_CYCLES_ ?? totalCycles;
        faultCorrect.AIRCRAFT_ROUNDS_ = faultCorrect.AIRCRAFT_ROUNDS_ ?? 0;
    }
    await db.updateRecord('esnaadm','FAULT_UNITS',value,'FAULT_UNIT_ID_');
    await db.updateRecord('esnaadm','FAULT_CORRECTS',faultCorrect,'FAULT_CORRECT_ID_');
    await db.commit('esnaadm');
    page.var.refreshScreenKey.set(utils.guid());
}

