async function load() {
    if (correctingItemId) {
        const correctingItem = await db.find('esnaadm','FAULT_CORRECTING_ITEMS', { FAULT_CORRECTING_ITEM_ID_: correctingItemId });
        page.var.correctingItem.set(correctingItem);
    } else if(correctId) {
        const correct = await db.find('esnaadm','FAULT_CORRECTS',{FAULT_CORRECT_ID_:correctId});
        const corrects = await db.read('esnaadm','FAULT_CORRECTING_ITEMS',{FAULT_CORRECT_ID_:correctId},{RECORD_NO_:'desc'});
        const lastRecordNo = corrects.length > 0 ? corrects[0].RECORD_NO_ : 0;
        const now = utils.dateToString(new Date());
        const id = utils.uniqueNumber();
        page.var.correctingItem.set({
            USR_ID: null,
            CAT_ID: null,
            MOD_BY_: null,
            TI_USR_ID: null,
            STS_ID: null,
            CREATED_BY_: loggedInUser.USER_ID_,
            FAULT_UNIT_ID_: correct.FAULT_UNIT_ID_,
            RECORD_NO_: lastRecordNo + 1,
            UNIT_ID_: correct.UNIT_ID_,
            IDX_: lastRecordNo,
            GROUP_NO_: null,
            CREATED_ON_: now,
            FAULT_CORRECT_ID_: correct.FAULT_CORRECT_ID_,
            MNT_MAIN_HRS: null,
            TERM_: "ESNAADM",
            REL_ACT_: null,
            MAJOR_EVENT_ID: null,
            ACT_: null,
            MOD_ON_: null,
            FAULT_CORRECTING_ITEM_ID_: id
        });
        page.var.editMode.set(true);
    }
}

