cellStyleMapper.formula:
const colors = {
    'dash141' : '#F5AF00',
    'dash16' : '#996699',
    'prePostFlight' : '#A44747',
    'dash18' : '#006F00',
    'adhoc' : '#000000',
    'phase' : '#00B0F0',
    'mission' : '#1422D0'

}
module.exports = (params) => {

    const is14dash1 = params.rowData.FAULT_STATE_ === 'Uncorrecting';
    const isDash18 = !utils.isEmpty(params.rowData.INSP_ID);
    const isPrePostFlight = !utils.isEmpty(params.rowData.INT_OTHER_);
    const isMission = !utils.isEmpty(params.rowData.TAIL_FLIGHT_ID);
    let color = colors.adhoc;

    if(isDash18){
        color = colors.dash18;
    }

    if(isPrePostFlight){
        color = colors.prePostFlight;
    }

    if(is14dash1){
        color = colors.dash141;
    }
    
    if(isMission){
        color = colors.mission
    }
    return {...params.initialStyle,color}
}

