            "ACTUAL_BASE_FROM_ID": form.departFrom, //null,
            "ACTUAL_BASE_TO_ID": form.arriveTo,// null,
            "CANCELLATION_REASON_ID": baseValue?.tailFlight?.CANCELLATION_REASON_ID,
            "CANCELLATION_REASON_RMKS_": baseValue?.tailFlight?.CANCELLATION_REASON_RMKS_
        }, 'TAIL_FLIGHT_ID_');

        db.updateRecord('esnaadm','TAIL_FLIGHT_RECORDS', {
            "MISSION_ID_": missionId,//11724,
            "UNIT_ID_": unitId,//224,
            "MISSION_TAIL_FLIGHT_RECORD_ID_": tailFlightRecordId,// 1277,
            "ENGINE_STARTS1_": form.engine1, // 0,
            "ENGINE_STARTS2_": form.engine2,//0,
            "LANDINGS_": form.landing, //1,
            "MISSION_CODE_": form.passengersCode,//0,
            "PASSENGERS_": form.passengers,//0,
            "RTA_": form.ata ? utils.dateToString(form.ata) : undefined,//"2019-09-15T02:10:00",
            "RTD_": form.atd ? utils.dateToString(form.atd) : undefined,//"2019-09-15T02:05:00",
            "TAIL_FLIGHT_ID": tailFlightId,//11867,
            "FLIGHT_MINS_": form.durationMinutes,//5,
            "TAAMS_FLIGHT_MINS_": form.durationMinutes,
            "SNAPSHOT_PLTF_CFG_ID_": baseValue?.tailFlightRecord?.SNAPSHOT_PLTF_CFG_ID_ ?? appContext.platformConfig.id,// "8A3A9759-D8BB-4414-AFB3-50D723513B27",
            "ROUNDS_762_": form.arm762, //null,
            "ROUNDS_20_": form.arm20,//null,
            "ROUNDS_30_": form.arm30,//null,
            "ROUNDS_40_": form.arm40,//null,
            "ROUNDS_ROCKET_": form.armRocket,//null,
            "ROUNDS_TOW_": form.armTow,//null,
            "ROUNDS_HELLFIRE_": form.armHellfire,//null,
            "ROUNDS_127_NAG_": form.arm127Nag,//null,
            "ROUNDS_20_NAG_": form.arm20Nag,//null,
            "ROUNDS_AM39_NAG_": form.arm39Nag,//null,
            "ROUNDS_TORPEDO_NAG_": form.armTorpedoNag,//null,
            "ROUNDS_AS15TT_NAG_": form.armAs15ttNag,//null,
            "CYCLES_": form.cycle,// 0,
            "EXTERNAL_LOAD_": form.extLoad,//0.0,
            "INTERNAL_LOAD_": form.intLoad,//0.0,
            "CREATED_BY_": baseValue?.tailFlightRecord?.CREATED_BY_ ?? currentUser.USER_ID_,// "GAL7535",
            "PID_CREATED_BY_": baseValue?.tailFlightRecord?.PID_CREATED_BY_ ?? currentUser.USER_ID_,// "GAL7535",
            "FULL_NAME_CREATED_BY_": baseValue?.tailFlightRecord?.FULL_NAME_CREATED_BY_ ?? `${currentUser.F_NAME_} ${currentUser.L_NAME_}`,// "KARTHIKEYAN JAYABALAN",
            "CREATED_ON_": baseValue?.tailFlightRecord?.CREATED_ON_ ?? utils.dateToString(now),// "2019-09-15T10:43:48.680",
            "MOD_BY_": currentUser.USER_ID_,// null,
            "PID_MOD_BY_": currentUser.USER_ID_,//null,
            "FULL_NAME_MOD_BY_": `${currentUser.F_NAME_} ${currentUser.L_NAME_}`,//null,
            "MOD_ON_": utils.dateToString(now),//null,
