        }, 'MISSION_TAIL_FLIGHT_RECORD_ID_');


        const crewFlights = await db.read('esnaadm','TAIL_CREW_FLIGHTS', { TAIL_FLIGHT_RECORD_ID: tailFlightRecordId });
