module.exports = async () => {
    const form = { ...formContext.value.get() };
    if (form.departFrom && form.atd) {
        const departureDate = form.atd;
        const result = await page.query.findAirBases({ filter: { ID_: { value: form.departFrom, type: 'equal' } } });
        const gmtDiff = result.data && result.data.length > 0 ? result.data[0].GMT_DIFF_ : 0; // gmt diff is in minutes
        const atdGmt = new Date(departureDate.getFullYear(), departureDate.getMonth(), departureDate.getDate(), departureDate.getHours(), departureDate.getMinutes() - gmtDiff);
        form.atdGmt = atdGmt;
        if (form.ataGmt) {
            const duration = form.ataGmt.getTime() - form.atdGmt.getTime();
