validator.formula:
module.exports = async () => {
    const form = formContext.value.get();
    if (form === undefined || form.pilotsAndCrews === undefined || form.pilotsAndCrews.length < 2 ) {
        return 'At least 2 crews is required';
    }
    
    const errors = [];
    for (const pilotCrew of form.pilotsAndCrews){
        const crew = await db.find('esnaadm','OPS_MST_FLIGHT_CREWS',{ID_:pilotCrew.crewId});
        const person = await db.find('esnaadm','ADM_TRN_USER_PROFILES',{ID_:crew.PERSON_ID});
        const name = [person.F_NAME_,person.M_NAME_,person.L_NAME_].filter(i => i).join(' ')
        
        if(pilotCrew.hours.filter(i => i.dsId > 0 || i.fsId > 0 || i.hr > 0 || (!utils.isEmpty(i.sId))).length < 1){
            errors.push(`<div><span style="font-weight:bold">${name}'s</span> duty information is incomplete</div>`);
        }
        let segmentIndex = 1;
        for(const hour of pilotCrew.hours){
            const hasAnyValue = hour.dsId > 0 || hour.fsId > 0 || hour.hr > 0 || (!utils.isEmpty(hour.sId))
            const isComplete = hour.dsId > 0 && hour.fsId > 0 && hour.hr > 0 && (!utils.isEmpty(hour.sId))
            if(hasAnyValue && (!isComplete)){
                const missingSymbol = [];
                if(!(hour.dsId > 0)){
                    missingSymbol.push('DS');
                }
                if(!(hour.fsId > 0)){
                    missingSymbol.push('FS');
                }
                if(!(hour.hr > 0)){
                    missingSymbol.push('HR');
                }
                if(utils.isEmpty(hour.sId)){
                    missingSymbol.push('S');
                }
                errors.push(`<div><span style="font-weight:bold">${name}</span> segment #${segmentIndex} is missing <span style="font-style:italic">${missingSymbol.join(', ')}</span></div>`);
            }
            segmentIndex++;
        }
    }

    return errors.join('');
}

